namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            MakeNotification("Welcome to the notification center!"),
            MakeNotification("Your profile was updated successfully."),
            MakeNotification("New comment on your post."),
        });
    }

    /// <summary>Returns all notifications.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>Simulate a new notification arriving roughly every 10 seconds.</summary>
    public void SimulateIncoming()
    {
        lock (_lock)
        {
            // ~30 % chance per call (called every 5 s → roughly one new item every 15 s)
            if (Random.Shared.Next(100) < 30)
            {
                var messages = new[]
                {
                    "Someone liked your post.",
                    "You have a new follower.",
                    "Deployment succeeded.",
                    "Disk usage alert: 90 % full.",
                    "Scheduled backup completed.",
                };
                _notifications.Add(
                    MakeNotification(messages[Random.Shared.Next(messages.Length)]));
            }
        }
    }

    private Notification MakeNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@using NotificationsApp.Services
@inject NotificationService Svc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in _notifications.OrderByDescending(x => x.Id))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    // Runs during both prerender AND interactive start.
    protected override void OnInitialized()
    {
        _notifications = Svc.GetAll();
    }

    // Runs only once after the component is interactive in the browser.
    // This is the right place to start the polling loop — it does NOT fire
    // during static/prerender, so no background work leaks on the server.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        // Track the highest id we already have so we only fetch new ones.
        var lastSeenId = _notifications.Count > 0
            ? _notifications.Max(n => n.Id)
            : 0;

        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }

            // Give the service a chance to generate a fake notification.
            Svc.SimulateIncoming();

            var newer = Svc.GetSince(lastSeenId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                lastSeenId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

