+            <li class="list-group-item d-flex justify-content-between align-items-start">
+                <span>@n.Message</span>
+                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
+            </li>
+        }
+    </ul>
+}
+
+@code {
+    private List<Notification> _notifications = new();
+    private CancellationTokenSource? _cts;
+
+    // Runs during both prerender AND interactive start.
+    protected override void OnInitialized()
+    {
+        _notifications = Svc.GetAll();
+    }
+
+    // Runs only once after the component is interactive in the browser.
+    // This is the right place to start the polling loop — it does NOT fire
+    // during static/prerender, so no background work leaks on the server.
+    protected override void OnAfterRender(bool firstRender)
+    {
+        if (firstRender)
+        {
+            _cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(_cts.Token);
+        }
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken ct)
+    {
+        // Track the highest id we already have so we only fetch new ones.
+        var lastSeenId = _notifications.Count > 0
+            ? _notifications.Max(n => n.Id)
+            : 0;
+
+        while (!ct.IsCancellationRequested)
+        {
+            try
+            {
+                await Task.Delay(TimeSpan.FromSeconds(5), ct);
+            }
+            catch (TaskCanceledException)
+            {
+                break;
+            }
+
+            // Give the service a chance to generate a fake notification.
+            Svc.SimulateIncoming();
+
+            var newer = Svc.GetSince(lastSeenId);
+            if (newer.Count > 0)
+            {
+                _notifications.AddRange(newer);
+                lastSeenId = newer.Max(n => n.Id);
+                await InvokeAsync(StateHasChanged);
+            }
+        }
+    }
+
+    public void Dispose()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+    }
+}
